-- Report ID : RPT_307
-- Report    : Location Detail
-- Module    : Foundation
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     'Store'                     AS LOCATION_TYPE,     s.STORE                     AS LOCATION_ID,     s.STORE_NAME                AS LOCATION_NAME,     s.STORE_NAME10              AS LOCATION_NAME_SHORT,     CASE         WHEN s.STORE_CLOSE_DATE IS NOT NULL          AND s.STORE_CLOSE_DATE <= SYSDATE THEN 'Closed'         WHEN s.STORE_OPEN_DATE > SYSDATE   THEN 'Pre-Open'         ELSE 'Active'     END                         AS STATUS,     s.STORE_CLASS,     s.STORE_TYPE,     TO_CHAR(s.STORE_FORMAT)     AS STORE_FORMAT,     TO_CHAR(s.DISTRICT)         AS DISTRICT,     TO_CHAR(s.CHANNEL_ID)       AS CHANNEL_ID,     s.CURRENCY_CODE,     s.TIMEZONE_NAME,     s.STOCKHOLDING_IND,     s.STORE_MGR_NAME            AS MANAGER_NAME,     s.PHONE_NUMBER,     s.FAX_NUMBER,     s.EMAIL,     s.STORE_OPEN_DATE           AS OPEN_DATE,     s.STORE_CLOSE_DATE          AS CLOSE_DATE,     s.ACQUIRED_DATE,     s.REMODEL_DATE,     s.TOTAL_SQUARE_FT,     s.SELLING_SQUARE_FT,     s.LINEAR_DISTANCE,     TO_CHAR(s.DEFAULT_WH)       AS DEFAULT_WH,     s.ONLINE_STORE_IND          AS ONLINE_IND,     s.CUSTOMER_ORDER_LOC_IND,     TO_CHAR(s.VAT_REGION)       AS VAT_REGION,     s.VAT_INCLUDE_IND,     s.LEGAL_ENTITY,     s.TAX_ID,     a.ADD_1, a.ADD_2, a.ADD_3,     a.CITY, a.STATE,     a.POST                      AS ZIP_CODE,     a.COUNTRY_ID, a.COUNTY,     a.LATITUDE, a.LONGITUDE FROM rds_wv_store s LEFT JOIN rds_wv_addr a     ON  a.MODULE            = 'ST'     AND a.KEY_VALUE_1       = TO_CHAR(s.STORE)     AND a.PRIMARY_ADDR_IND  = 'Y'     AND a.ADDR_TYPE         = '01' UNION ALL SELECT     CASE         WHEN w.PHYSICAL_WH = w.WH THEN 'Physical Warehouse'         ELSE 'Virtual Warehouse'     END                         AS LOCATION_TYPE,     w.WH                        AS LOCATION_ID,     w.WH_NAME                   AS LOCATION_NAME,     NULL                        AS LOCATION_NAME_SHORT,     'Active'                    AS STATUS,     NULL                        AS STORE_CLASS,     w.VWH_TYPE                  AS STORE_TYPE,     NULL                        AS STORE_FORMAT,     NULL                        AS DISTRICT,     TO_CHAR(w.CHANNEL_ID)       AS CHANNEL_ID,     w.CURRENCY_CODE,     NULL                        AS TIMEZONE_NAME,     w.STOCKHOLDING_IND,     NULL                        AS MANAGER_NAME,     NULL                        AS PHONE_NUMBER,     NULL                        AS FAX_NUMBER,     w.EMAIL,     NULL                        AS OPEN_DATE,     NULL                        AS CLOSE_DATE,     NULL                        AS ACQUIRED_DATE,     NULL                        AS REMODEL_DATE,     NULL                        AS TOTAL_SQUARE_FT,     NULL                        AS SELLING_SQUARE_FT,     NULL                        AS LINEAR_DISTANCE,     TO_CHAR(w.DEFAULT_WH)       AS DEFAULT_WH,     NULL                        AS ONLINE_IND,     w.CUSTOMER_ORDER_LOC_IND,     TO_CHAR(w.VAT_REGION)       AS VAT_REGION,     NULL                        AS VAT_INCLUDE_IND,     w.LEGAL_ENTITY,     w.TAX_ID,     a.ADD_1, a.ADD_2, a.ADD_3,     a.CITY, a.STATE,     a.POST                      AS ZIP_CODE,     a.COUNTRY_ID, a.COUNTY,     a.LATITUDE, a.LONGITUDE FROM rds_wv_wh w LEFT JOIN rds_wv_addr a     ON  a.MODULE            = 'WH'     AND a.KEY_VALUE_1       = TO_CHAR(w.WH)     AND a.PRIMARY_ADDR_IND  = 'Y'     AND a.ADDR_TYPE         = '01'